// ── Normalizza corse ──────────────────────────────────────────

const corse = ($json.corse || []).map(c => ({
  data:      c.data_uscita,
  ora:       c.ora_uscita || null,
  entrata:   c.stazione_entrata || null,
  uscita:    c.stazione_uscita  || null,
  importo:   c.importo
}));

// ── pageContent ───────────────────────────────────────────────

const corse_testo = corse.map(c =>
  `${c.data} ore ${c.ora}: ${c.entrata} → ${c.uscita} (${c.importo}€)`
).join('; ');

// Città uniche coinvolte — utile per query tipo "viaggi verso Trieste"
const citta = [...new Set(
  corse.flatMap(c => [c.entrata, c.uscita]).filter(Boolean)
)];

const pageContent = [
  `Estratto conto pedaggi autostradali MooneyGo.`,
  `Periodo dal ${$json.periodo_dal} al ${$json.periodo_al}.`,
  `Numero fattura: ${$json.numero_fattura}.`,
  `Data emissione: ${$json.data_bolletta}.`,
  `Importo totale: ${$json.importo_bolletta}€.`,
  `Numero corse: ${corse.length}.`,
  `Stazioni coinvolte: ${citta.join(', ')}.`,
  `Dettaglio corse: ${corse_testo}.`
].join(' ');

// ── metadata ──────────────────────────────────────────────────

const metadata = {
  id:             $json.id,
  type:           $json.type,
  acquisito_il:   $json.acquisito_il || new Date().toISOString(),
  fornitore:      'MooneyGo',
  tipo_utenza:    ['pedaggi'],
  numero_fattura: $json.numero_fattura || null,
  periodo_dal:    $json.periodo_dal,
  periodo_al:     $json.periodo_al,
  emissione:      $json.data_bolletta || null,
  importo_totale: $json.importo_bolletta,
  numero_corse:   corse.length,
  citta:          citta   // array — filtrabile con match: { any: [...] }
};

return {
  json: {
    pageContent,
    metadata
  }
};

// ── pageContent ───────────────────────────────────────────────
// Testo in linguaggio naturale ottimizzato per l'embedding.
// Campi opzionali inclusi solo se presenti.

const tipi = ($json.tipo_utenza || []).join(' e ');

const consumi_testo = ($json.consumi || [])
  .map(c => `${c.tipo} ${c.valore} ${c.unita} (${c.importo}€)`)
  .join(', ');

const parts = [
  `Bolletta ${tipi} fornitore ${$json.fornitore}.`,
  `Periodo dal ${$json.periodo_dal} al ${$json.periodo_al}.`,
  consumi_testo ? `Consumi: ${consumi_testo}.` : null,
  `Importo totale: ${$json.importo_totale}€.`,
  $json.numero_fattura ? `Numero fattura: ${$json.numero_fattura}.` : null,
  $json.emissione      ? `Data emissione: ${$json.emissione}.`      : null,
  $json.scadenza       ? `Scadenza pagamento: ${$json.scadenza}.`   : null,
];

const pageContent = parts.filter(Boolean).join(' ');

// ── metadata (payload Qdrant) ─────────────────────────────────
// Solo campi presenti — undefined esclusi da Qdrant automaticamente,
// ma lo filtriamo esplicitamente per chiarezza.

const metadata = Object.fromEntries(
  Object.entries({
    id:             $json.id,
    type:           $json.type,
    acquisito_il:   $json.acquisito_il   || null,
    fornitore:      $json.fornitore      || null,
    tipo_utenza:    $json.tipo_utenza    || null,   // array: ["luce","gas"]
    numero_fattura: $json.numero_fattura || null,
    periodo_dal:    $json.periodo_dal    || null,
    periodo_al:     $json.periodo_al     || null,
    emissione:      $json.emissione      || null,
    scadenza:       $json.scadenza       || null,
    importo_totale: $json.importo_totale ?? null,
    // Appiattisce i consumi per filtri diretti (es. importo_luce, importo_gas)
    ...Object.fromEntries(
      ($json.consumi || []).map(c => [
        `consumo_${c.tipo}`,
        { valore: c.valore, unita: c.unita, importo: c.importo }
      ])
    )
  }).filter(([, v]) => v !== null)
);

return {
  json: {
    pageContent,
    metadata
  }
};
